USE mccollins_shipping;SET time_zone='+00:00';START TRANSACTION;
INSERT INTO permissions(permission_code,domain_code,action_code,sensitivity,is_active)SELECT x.c,'system',x.a,x.s,1 FROM(
SELECT 'NOTIFICATION_VIEW_OWN' c,'view_notifications' a,'normal' s UNION ALL SELECT 'NOTIFICATION_MANAGE','manage_notifications','sensitive'
UNION ALL SELECT 'AUDIT_VIEW_ALL','view_audit','restricted' UNION ALL SELECT 'ACCESS_LOG_VIEW','view_access_logs','restricted'
)x WHERE NOT EXISTS(SELECT 1 FROM permissions p WHERE p.permission_code=x.c);
INSERT INTO role_permissions(role_id,permission_id,scope_class,effective_from,status)SELECT r.role_id,p.permission_id,'owner',UTC_TIMESTAMP(6),'active' FROM roles r JOIN permissions p ON p.permission_code='NOTIFICATION_VIEW_OWN' WHERE r.role_code IN('MCCOLLIN_OPERATIONS','MCCOLLIN_FINANCE','SYSTEM_ADMIN','COMPLIANCE_SUPPORT','SHIPPER','TRUCK_OWNER','DRIVER','CF_AGENCY','FARMER_AMCOS','BUYER','SUPPLIER')AND NOT EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id AND rp.status='active');
INSERT INTO role_permissions(role_id,permission_id,scope_class,effective_from,status)SELECT r.role_id,p.permission_id,'global',UTC_TIMESTAMP(6),'active' FROM roles r JOIN permissions p ON(r.role_code='SYSTEM_ADMIN' AND p.permission_code IN('NOTIFICATION_MANAGE','AUDIT_VIEW_ALL','ACCESS_LOG_VIEW'))OR(r.role_code='MCCOLLIN_OPERATIONS' AND p.permission_code IN('NOTIFICATION_MANAGE','AUDIT_VIEW_ALL','ACCESS_LOG_VIEW'))WHERE NOT EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id AND rp.status='active');COMMIT;